machines.shape:
// the template reads the column called "order" as m.order
msg.payload = msg.payload || [];
return msg;

orders.query:
// Latest production orders
msg.query = `
SELECT o.order_number, a.asset_code, o.part_number, o.completed_quantity, o.scrap_quantity,
       o.target_quantity, o.status, o.released_at
  FROM mf.production_orders o LEFT JOIN mf.assets a ON a.id = o.asset_id
 ORDER BY (o.status IN ('released','running')) DESC, o.released_at DESC
 LIMIT 10
`;
msg.params = [];
return msg;

orders.shape:
const rows = msg.payload || [];
msg.payload = rows.map((o) => ({
    Order: o.order_number,
    Machine: o.asset_code,
    Part: o.part_number,
    Progress: `${o.completed_quantity} / ${o.target_quantity}`,
    Scrap: o.scrap_quantity,
    Status: o.status,
}));
return msg;

workrequests.query:
// Latest maintenance work requests
msg.query = `
SELECT r.request_number, a.asset_code, r.reason_code, r.assigned_to, r.status, r.opened_at, r.closed_at
  FROM mf.maintenance_requests r JOIN mf.assets a ON a.id = r.asset_id
 ORDER BY r.opened_at DESC, r.id DESC LIMIT 8
`;
msg.params = [];
return msg;

workrequests.shape:
const t = (v) => (v ? new Date(v).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '');
msg.payload = (msg.payload || []).map((r) => ({
    Request: r.request_number,
    Machine: r.asset_code,
    Reason: r.reason_code,
    'Assigned to': r.assigned_to,
    Status: r.status,
    Opened: t(r.opened_at),
    Closed: t(r.closed_at),
}));
return msg;

receipts.query:
// Production receipts sent back to the ERP
msg.query = `
SELECT order_number, part_number, good_quantity, scrap_quantity, received_at
  FROM demo_erp.production_receipts ORDER BY received_at DESC LIMIT 6
`;
msg.params = [];
return msg;

receipts.shape:
const t = (v) => (v ? new Date(v).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '');
msg.payload = (msg.payload || []).map((r) => ({
    Order: r.order_number, Part: r.part_number, Good: r.good_quantity, Scrap: r.scrap_quantity, Received: t(r.received_at),
}));
return msg;

feed.query:
// Recent notices (alerts, work requests, recoveries)
msg.query = `
SELECT n.created_at, n.severity, n.title, n.message, (n.delivered_at IS NOT NULL) AS sent
  FROM mf.notifications n ORDER BY n.created_at DESC, n.id DESC LIMIT 10
`;
msg.params = [];
return msg;

feed.shape:
const t = (v) => (v ? new Date(v).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '');
msg.payload = (msg.payload || []).map((n) => ({
    Time: t(n.created_at), Level: n.severity, Notice: n.title, Detail: n.message, 'Sent outside': n.sent ? 'yes' : '',
}));
return msg;

settings.query:
// Every setting the flows read at run time
msg.query = `
SELECT key, value, description, updated_at FROM mf.settings ORDER BY key
`;
msg.params = [];
return msg;

settings.shape:
const t = (v) => (v ? new Date(v).toLocaleString('en-GB') : '');
msg.payload = (msg.payload || []).map((s) => ({
    Setting: s.key, Value: JSON.stringify(s.value), What: s.description, Changed: t(s.updated_at),
}));
return msg;

reasons.query:
// Fault catalogue
msg.query = `
SELECT code, description, asset_type, severity, assigned_to, active FROM mf.reason_codes ORDER BY asset_type NULLS FIRST, code
`;
msg.params = [];
return msg;

reasons.shape:
msg.payload = (msg.payload || []).map((r) => ({
    Code: r.code, Meaning: r.description, 'Machine type': r.asset_type || 'any', Severity: r.severity,
    'Assigned to': r.assigned_to || '(default)', Active: r.active ? 'yes' : 'no',
}));
return msg;

machinelist.query:
// Machines in the plant
msg.query = `
SELECT a.asset_code, a.name, ar.name AS area, a.asset_type, a.default_part_number, a.ideal_cycle_seconds
  FROM mf.assets a LEFT JOIN mf.areas ar ON ar.id = a.area_id ORDER BY a.asset_code
`;
msg.params = [];
return msg;

machinelist.shape:
msg.payload = (msg.payload || []).map((m) => ({
    Code: m.asset_code, Name: m.name, Area: m.area, Type: m.asset_type, Part: m.default_part_number, 'Cycle (s)': m.ideal_cycle_seconds,
}));
return msg;

plant.query:
// Plant name shown at the top of the dashboard (Settings page: plant_name)
msg.query = `SELECT value #>> '{}' AS name FROM mf.settings WHERE key = 'plant_name'`;
msg.params = [];
return msg;
